package com.deardiary.privateapp;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import androidx.core.content.FileProvider;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
final class AppUpdater{
 private final MainActivity host;private boolean checked=false,downloading=false;private int epoch=0;private JSONObject offered;private File pending;private AlertDialog sheet;private TextView status;private Button update;
 AppUpdater(MainActivity h){host=h;File folder=new File(h.getCacheDir(),"updates");File[] stale=folder.listFiles();if(stale!=null)for(File f:stale)f.delete();}
 private int code(){try{return(int)host.getPackageManager().getPackageInfo(host.getPackageName(),0).getLongVersionCode();}catch(Exception e){return Integer.MAX_VALUE;}}
 void reset(){epoch++;checked=false;offered=null;pending=null;if(sheet!=null)sheet.dismiss();}
 void background(){if(!downloading)checked=false;}
 void ready(){if(!checked&&!downloading&&host.canUpdate()){checked=true;request("check",0);}}
 private void request(String action,int target){host.updateEvent(action,code(),target);}
 void result(JSONObject d){if(!host.canUpdate())return;if(d.optString("op").equals("update-error")){if(status!=null)status.setText("Could not check or download the update. Check your connection and try again.");if(update!=null)update.setEnabled(true);return;}
  if(!d.optBoolean("available",false)||d.optInt("code")<=code())return;
  if(d.optString("action").equals("download")){if(offered==null||d.optInt("code")!=offered.optInt("code")||!d.optString("sha256").equals(offered.optString("sha256")))return;download(d);return;}
  offered=d;show();
 }
 private void show(){if(sheet!=null&&sheet.isShowing())return;LinearLayout layout=new LinearLayout(host);layout.setOrientation(LinearLayout.VERTICAL);int pad=(int)(24*host.getResources().getDisplayMetrics().density);layout.setPadding(pad,pad,pad,pad);TextView title=new TextView(host);title.setText("Dear Diary "+offered.optString("version"));title.setTextSize(24);layout.addView(title);TextView notes=new TextView(host);notes.setText(offered.optString("notes")+"\n\nAndroid will ask you to confirm installation. Your diary stays in the same app. Reopen Dear Diary if Android does not reopen it.");notes.setTextSize(16);ScrollView scroll=new ScrollView(host);scroll.addView(notes);layout.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));status=new TextView(host);status.setText("A newer private release is ready.");layout.addView(status);update=new Button(host);update.setText("Update");update.setOnClickListener(v->{if(pending!=null){install();return;}update.setEnabled(false);status.setText("Getting a fresh private download...");request("download",offered.optInt("code"));});layout.addView(update);sheet=new AlertDialog.Builder(host).setView(layout).create();sheet.setOnShowListener(d->{sheet.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);sheet.getWindow().setLayout(-1,(int)(host.getResources().getDisplayMetrics().heightPixels*.86));});sheet.show();}
 private void download(JSONObject d){if(downloading)return;String url=d.optString("url"),sha=d.optString("sha256");long bytes=d.optLong("bytes");int version=d.optInt("code");
  if(!url.startsWith("https://etkjcywiaiiphsrthxqe.supabase.co/storage/v1/object/sign/private-android-releases/")||!sha.matches("[0-9a-f]{64}")||bytes<1||bytes>30000000){fail("Update details could not be verified.");return;}
  downloading=true;final int attempt=epoch;status.setText("Downloading update inside Dear Diary...");new Thread(()->{File file=null;HttpURLConnection connection=null;try{File dir=new File(host.getCacheDir(),"updates");dir.mkdirs();file=new File(dir,"release-"+version+".apk");connection=(HttpURLConnection)new URL(url).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(20000);connection.setReadTimeout(30000);if(connection.getResponseCode()!=200)throw new IOException();MessageDigest hash=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(file)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){count+=n;if(count>bytes)throw new IOException();hash.update(buffer,0,n);out.write(buffer,0,n);}}
   if(count!=bytes||!hex(hash.digest()).equals(sha)||!verify(file,version))throw new SecurityException();final File verified=file;host.runOnUiThread(()->{downloading=false;if(attempt!=epoch||!host.canUpdate()){verified.delete();return;}pending=verified;status.setText("Download verified. Opening Android installer...");update.setEnabled(true);install();});
  }catch(Exception e){if(file!=null)file.delete();host.runOnUiThread(()->{downloading=false;if(attempt==epoch)fail("Update download failed verification or connection. Tap Update to retry with a fresh link.");});}finally{if(connection!=null)connection.disconnect();}},"diary-update").start();
 }
 private boolean verify(File file,int version)throws Exception{PackageManager pm=host.getPackageManager();PackageInfo apk=pm.getPackageArchiveInfo(file.getAbsolutePath(),PackageManager.GET_SIGNING_CERTIFICATES),installed=pm.getPackageInfo(host.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);if(apk==null||!host.getPackageName().equals(apk.packageName)||apk.getLongVersionCode()!=version||version<=installed.getLongVersionCode()||apk.signingInfo==null||installed.signingInfo==null)return false;
  android.content.pm.Signature[] incoming=apk.signingInfo.getApkContentsSigners(),current=installed.signingInfo.getApkContentsSigners();if(incoming.length!=1||current.length!=1)return false;return MessageDigest.isEqual(incoming[0].toByteArray(),current[0].toByteArray());
 }
 void install(){if(pending==null||offered==null||!host.canUpdate())return;try{if(!verify(pending,offered.optInt("code")))throw new SecurityException();if(!host.getPackageManager().canRequestPackageInstalls()){status.setText("Allow Dear Diary to install its updates, then return here. Android will still ask you to confirm Install.");host.updateExternal(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+host.getPackageName())),87);return;}Uri uri=FileProvider.getUriForFile(host,host.getPackageName()+".updates",pending);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);status.setText("Confirm Install in Android. If cancelled, tap Update to try again.");host.updateExternal(intent,88);}catch(Exception e){fail("Could not open Android's installer. The existing app has not changed.");}}
 void returned(int request){if(request==87&&host.getPackageManager().canRequestPackageInstalls())install();}
 private void fail(String text){if(status!=null)status.setText(text);if(update!=null)update.setEnabled(true);}
 static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format("%02x",b));return s.toString();}
}
